    internal InnerServiceBearerTokenDetailsFactory BearerTokenFactory { get; set; }

    protected override Humidifier.DevOpsAgent.ServiceTypes.MCPServerAuthorizationConfig Create()
    {
        var mCPServerAuthorizationConfigResult = CreateMCPServerAuthorizationConfig();
        factoryAction?.Invoke(mCPServerAuthorizationConfigResult);

        return mCPServerAuthorizationConfigResult;
    }

    private Humidifier.DevOpsAgent.ServiceTypes.MCPServerAuthorizationConfig CreateMCPServerAuthorizationConfig()
    {
        var mCPServerAuthorizationConfigResult = new Humidifier.DevOpsAgent.ServiceTypes.MCPServerAuthorizationConfig();

        return mCPServerAuthorizationConfigResult;
    }
    public override void CreateChildren(Humidifier.DevOpsAgent.ServiceTypes.MCPServerAuthorizationConfig result)
    {
        base.CreateChildren(result);

        result.ApiKey ??= ApiKeyFactory?.Build();
        result.OAuthClientCredentials ??= OAuthClientCredentialsFactory?.Build();
        result.BearerToken ??= BearerTokenFactory?.Build();
    }

} // End Of Class

